// Expected body: { email, subject?, message, channel? }
const b = $input.first().json.body ?? $input.first().json;
if (!b.email || !b.message) { throw new Error('Question missing email or message'); }
const channels = ['Correspondence Form', 'Email', 'Instagram DM', 'Other'];
return [{ json: {
  email: String(b.email).trim().toLowerCase(),
  subject: (b.subject || 'Correspondence').slice(0, 200),
  message: String(b.message).slice(0, 4000),
  channel: channels.includes(b.channel) ? b.channel : 'Correspondence Form'
} }];

