const q = $('Normalize Question').first().json;
const text = ($input.first().json.content?.[0]?.text) || '{}';
const match = text.match(/\{[\s\S]*\}/);
let out = { answer: '', needs_human: true, reason: 'parse failure' };
try { out = { ...out, ...JSON.parse(match ? match[0] : text) }; } catch (e) { /* keep needs_human */ }
if (!out.answer || out.answer.length < 20) { out.needs_human = true; out.reason = out.reason || 'empty answer'; }
const chunks = [];
const a = String(out.answer || '');
for (let i = 0; i < a.length && chunks.length < 90; i += 1900) { chunks.push({ text: { content: a.slice(i, i + 1900) } }); }
return [{ json: { ...q, answerChunks: chunks, needsHuman: Boolean(out.needs_human), reason: String(out.reason || '') } }];

const results = $input.first().json.results || [];
return results.map(r => ({ json: {
  pageId: r.id,
  email: r.properties?.['From Email']?.email,
  subject: r.properties?.Subject?.title?.[0]?.plain_text || 'Correspondence — Donum Dei Performance',
  answer: (r.properties?.['Draft Answer']?.rich_text || []).map(t => t.plain_text).join('')
} })).filter(i => i.json.email && i.json.answer);
